  `user_id` int NOT NULL,
  `return_reason` text,
  `return_status` enum('REQUESTED','APPROVED','REJECTED','PICKED_UP','REFUNDED') DEFAULT 'REQUESTED',
  `requested_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `pickup_date` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`return_id`),
  KEY `order_id` (`order_item_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `fk_return_order_item` FOREIGN KEY (`order_item_id`) REFERENCES `order_item` (`order_item_id`),
  CONSTRAINT `return_request_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
