CREATE TABLE `review` (
  `review_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `product_id` int NOT NULL,
  `rating` int DEFAULT NULL,
  `review_text` text,
  `sentiment_score` decimal(5,2) DEFAULT NULL,
  `review_status` enum('VISIBLE','HIDDEN','FLAGGED') DEFAULT 'VISIBLE',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `sentiment_label` enum('POSITIVE','NEGATIVE','NEUTRAL') DEFAULT 'POSITIVE',
  PRIMARY KEY (`review_id`),
  KEY `user_id` (`user_id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `review_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `review_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `product` (`product_id`),
  CONSTRAINT `review_chk_1` CHECK ((`rating` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
