INSERT INTO `review` VALUES (1,16,4,5,'The performance of this Dell laptop is outstanding. Blazing fast compile times and sleek layout!',0.95,'VISIBLE','2026-05-23 04:30:00','POSITIVE'),(2,16,5,4,'Great noise cancellation clarity on these Sony headphones. Bass signature is deep but clear.',0.82,'VISIBLE','2026-05-23 04:45:00','POSITIVE'),(3,17,1,5,'Perfect running fit! The Nike dry-fit moisture control feels light during heavy training routines.',0.91,'VISIBLE','2026-05-22 03:30:00','POSITIVE'),(4,17,2,4,'Very cozy track pants. Adidas quality holds up nicely after multiple aggressive wash cycles.',0.76,'VISIBLE','2026-05-22 04:00:00','POSITIVE'),(5,17,3,2,'Soles are a bit too rigid for competitive long-distance road running. Disappointed by the design.',-0.45,'VISIBLE','2026-05-24 08:30:00','NEGATIVE'),(6,18,31,5,'The iPhone 15 displays exceptional battery efficiency. The camera resolution is unmatched.',0.97,'VISIBLE','2026-05-23 05:30:00','POSITIVE'),(7,18,40,5,'Unbelievable ecosystem performance. Dynamic audio transparency mode isolates noise flawlessly.',0.93,'VISIBLE','2026-05-23 06:00:00','POSITIVE'),(8,19,21,4,'Premium denim feel. The Levis slim fit stretches comfortably without losing structural shape.',0.85,'VISIBLE','2026-05-25 10:30:00','POSITIVE'),(9,19,22,5,'Excellent corporate attire. Formal ironed fit remains clean all day long. Highly recommended.',0.89,'VISIBLE','2026-05-25 10:45:00','POSITIVE'),(10,20,6,5,'The biometric sensor tracking accuracy on this watch is reliable. Solid battery runtime.',0.88,'VISIBLE','2026-05-26 07:30:00','POSITIVE'),(11,1,31,5,'Absolutely spectacular device! Upgrading to this iOS performance was completely worth it.',0.96,'VISIBLE','2026-05-27 06:30:00','POSITIVE'),(12,2,6,1,'The smartwatch software keeps crashing constantly during workouts. Total waste of budget.',-0.85,'FLAGGED','2026-05-28 05:30:00','NEGATIVE'),(13,23,1,5,'Amazing t-shirt, fits perfectly for daily morning runs. Fabric is highly breathable.',0.92,'VISIB